import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.CS-cBh1g.js";const m=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md"}'),n={name:"guide/installation.md"};function i(r,e,d,l,h,p){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>You need the desktop app on the laptops your team uses, and the C++ library in your robot code. Node is only needed if you run Mayhem&#39;s command-line tools or connect an agent.</p><h2 id="desktop-app" tabindex="-1">Desktop app <a class="header-anchor" href="#desktop-app" aria-label="Permalink to &quot;Desktop app&quot;">​</a></h2><p>Get the latest installer from <a href="https://github.com/ryanabraham1/Mayhem/releases/latest" target="_blank" rel="noreferrer">GitHub Releases</a>:</p><table tabindex="0"><thead><tr><th>System</th><th>File to download</th></tr></thead><tbody><tr><td>macOS, Apple Silicon</td><td><code>Mayhem_*_aarch64.dmg</code></td></tr><tr><td>macOS, Intel</td><td><code>Mayhem_*_x64.dmg</code></td></tr><tr><td>Windows 10/11 (x64)</td><td><code>Mayhem_*_x64-setup.exe</code></td></tr><tr><td>Linux</td><td><code>.AppImage</code> (portable) or <code>.deb</code> (Ubuntu/Debian)</td></tr></tbody></table><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><p>Open the <code>.dmg</code> and drag Mayhem into Applications. These builds are not notarized, so if macOS blocks the first launch, run this once in Terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-dark github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B392F0;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> -dr</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> /Applications/Mayhem.app</span></span></code></pre></div><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p>Run the setup program. It installs for your user only, without an admin prompt. The installer is not code-signed, so if SmartScreen stops it, click <strong>More info</strong>, then <strong>Run anyway</strong>.</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><p>Make the <code>.AppImage</code> executable and run it, or install the <code>.deb</code>.</p><h3 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h3><p>Mayhem updates itself. A banner appears when a new release is out; click <strong>Install &amp; restart</strong>. You can also check in <strong>Settings → Updates</strong>.</p><h2 id="c-library-robot-code" tabindex="-1">C++ library (robot code) <a class="header-anchor" href="#c-library-robot-code" aria-label="Permalink to &quot;C++ library (robot code)&quot;">​</a></h2><p>Your robot runs Mayhem routines and state machines with the header-only <strong>MayhemCpp</strong> library. In VS Code with the WPILib extension, open the command palette (<kbd>Ctrl</kbd>/<kbd>Cmd</kbd>+<kbd>Shift</kbd>+<kbd>P</kbd>), run <strong>WPILib: Manage Vendor Libraries</strong>, choose <strong>Install new libraries (online)</strong>, and paste:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-dark github-dark vp-code" tabindex="0"><code><span class="line"><span>https://ryanabraham1.github.io/Mayhem/MayhemCpp.json</span></span></code></pre></div><p>Offline installs and copying the headers into the repo instead are covered in <a href="/Mayhem/robot-code/setup">Set up a robot repo</a>.</p><h2 id="command-line-tools-optional" tabindex="-1">Command-line tools (optional) <a class="header-anchor" href="#command-line-tools-optional" aria-label="Permalink to &quot;Command-line tools (optional)&quot;">​</a></h2><p>Exporting C++, checking generated code in CI and connecting agents use <code>scripts/mayhem.mjs</code>. It needs <strong>Node 24 or later</strong> and no <code>npm install</code>. Download <code>Mayhem-suite-tools-&lt;version&gt;.zip</code> from the same release, extract the whole folder, and run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B392F0;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> Mayhem-suite-tools-</span><span style="--shiki-light:#F97583;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#F97583;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;">/scripts/mayhem.mjs</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>A Mayhem source checkout works the same way. See <a href="/Mayhem/agents/tools">Command line and MCP tools</a>.</p><h2 id="browser-version" tabindex="-1">Browser version <a class="header-anchor" href="#browser-version" aria-label="Permalink to &quot;Browser version&quot;">​</a></h2><p>Most of the editing works in a browser from a source checkout (<code>cd app &amp;&amp; pnpm install &amp;&amp; pnpm dev</code>, then open <code>http://localhost:5173</code>). Reading robot code, log collection, live file links and deploys need the desktop app; see <a href="/Mayhem/suite/overview#desktop-vs-browser">Desktop vs. browser</a>.</p>',24)])])}const u=a(n,[["render",i]]);export{m as __pageData,u as default};
